  SetPlotTypes(decodeRows(PLOT_ROWS, {
    O = PlotTypes.PLOT_OCEAN, L = PlotTypes.PLOT_LAND,
    H = PlotTypes.PLOT_HILLS, M = PlotTypes.PLOT_MOUNTAIN
  }))
  GenerateCoasts()
end

function GenerateTerrain()
  local terrain = decodeRows(TERRAIN_ROWS, {
    O = GameInfoTypes.TERRAIN_OCEAN, C = GameInfoTypes.TERRAIN_COAST,
    G = GameInfoTypes.TERRAIN_GRASS, P = GameInfoTypes.TERRAIN_PLAINS,
    D = GameInfoTypes.TERRAIN_DESERT, T = GameInfoTypes.TERRAIN_TUNDRA,
    S = GameInfoTypes.TERRAIN_SNOW
  })
  for i = 0, Map.GetNumPlots() - 1 do
    Map.GetPlotByIndex(i):SetTerrainType(terrain[i + 1], false, false)
  end
end

function AddFeatures()
  local decoded = decodeRows(FEATURE_ROWS, {
    N = -1, F = GameInfoTypes.FEATURE_FOREST, A = GameInfoTypes.FEATURE_OASIS
  })
  for i = 0, Map.GetNumPlots() - 1 do
    if decoded[i + 1] ~= -1 then Map.GetPlotByIndex(i):SetFeatureType(decoded[i + 1], -1) end
  end
  local desert = GameInfoTypes.TERRAIN_DESERT
  local floodPlains = GameInfoTypes.FEATURE_FLOOD_PLAINS
  for i = 0, Map.GetNumPlots() - 1 do
    local plot = Map.GetPlotByIndex(i)
    if plot:GetTerrainType() == desert and plot:IsRiver() and not plot:IsMountain() then
      plot:SetFeatureType(floodPlains, -1)
    end
  end
end

function AddRivers()
  nextRiverID = 0
  _rivers = {}
  for _, river in ipairs(RIVER_GUIDES) do
    local source = Map.GetPlot(river.points[1][1], river.points[1][2])
    local corner = source and source:GetInlandCorner()
    if corner then
      ACTIVE_RIVER_GUIDE = river.points
      DoRiver(corner)
      ACTIVE_RIVER_GUIDE = nil
    end
  end
end

function GetRiverValueAtPlot(plot)
  if not ACTIVE_RIVER_GUIDE then return ORIGINAL_RIVER_VALUE(plot) end
  local bestValue = math.huge
  for index, waypoint in ipairs(ACTIVE_RIVER_GUIDE) do
    local distance = Map.PlotDistance(plot:GetX(), plot:GetY(), waypoint[1], waypoint[2])
    local value = distance * 100 + (#ACTIVE_RIVER_GUIDE - index) * 3
    if value < bestValue then bestValue = value end
  end
  if plot:IsWater() then bestValue = bestValue - 50 end
  return bestValue
end

function AddLakes()
  print("Historical Europe TSL: random lake generation disabled")
end

local function assignTSL()
  local claimed = {}
  for playerID = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
    local player = Players[playerID]
    if player and player:IsEverAlive() then
      local civ = GameInfo.Civilizations[player:GetCivilizationType()]
      local start = civ and TSL[civ.Type]
      if start then
        local x, y = start[1], start[2]
        local key = x .. ":" .. y
        if claimed[key] then x, y, key = start[3], start[4], start[3] .. ":" .. start[4] end
        local plot = Map.GetPlot(x, y)
        if plot and not plot:IsWater() and not plot:IsMountain() and not claimed[key] then
          player:SetStartingPlot(plot)
          claimed[key] = true
        end
      end
    end
  end
  local occupied = {}
  for playerID = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
    local player = Players[playerID]
    if player and player:IsEverAlive() then
      local plot = player:GetStartingPlot()
      if plot then occupied[#occupied + 1] = {plot:GetX(), plot:GetY()} end
    end
  end
  return occupied
end


local FOOD_RESOURCES = {
  [GameInfoTypes.RESOURCE_WHEAT] = true,
  [GameInfoTypes.RESOURCE_COW] = true,
  [GameInfoTypes.RESOURCE_SHEEP] = true,
  [GameInfoTypes.RESOURCE_DEER] = true,
  [GameInfoTypes.RESOURCE_FISH] = true
}


local function isNaturalWonder(plot)
  local featureID = plot:GetFeatureType()
  if featureID == -1 then return false end
  local feature = GameInfo.Features[featureID]
  return feature and (feature.NaturalWonder == true or feature.NaturalWonder == 1)
end


local function nearbyPlots(startPlot, maximumDistance)
  local candidates = {}
  local startX, startY = startPlot:GetX(), startPlot:GetY()
  for y = math.max(0, startY - maximumDistance), math.min(HEIGHT - 1, startY + maximumDistance) do
    for x = math.max(0, startX - maximumDistance), math.min(WIDTH - 1, startX + maximumDistance) do
      local distance = Map.PlotDistance(startX, startY, x, y)
      local plot = Map.GetPlot(x, y)
      if distance > 0 and distance <= maximumDistance and plot and not plot:IsMountain() and not isNaturalWonder(plot) then
        candidates[#candidates + 1] = {plot = plot, distance = distance, x = x, y = y}
      end
    end
  end
  table.sort(candidates, function(a, b)
    if a.distance ~= b.distance then return a.distance < b.distance end
    if a.y ~= b.y then return a.y < b.y end
    return a.x < b.x
  end)
  return candidates
end


local function preferredFoodResource(plot)
  if plot:IsWater() then
    if plot:GetTerrainType() == GameInfoTypes.TERRAIN_COAST then return GameInfoTypes.RESOURCE_FISH end
    return nil
  end
  if plot:IsHills() then return GameInfoTypes.RESOURCE_SHEEP end
  if plot:GetFeatureType() == GameInfoTypes.FEATURE_FOREST then return GameInfoTypes.RESOURCE_DEER end
  local terrain = plot:GetTerrainType()
  if terrain == GameInfoTypes.TERRAIN_GRASS then return GameInfoTypes.RESOURCE_COW end
  if terrain == GameInfoTypes.TERRAIN_TUNDRA then return GameInfoTypes.RESOURCE_DEER end
  return GameInfoTypes.RESOURCE_WHEAT
end


local function guaranteeStartingFood(startPlot)
  local candidates = nearbyPlots(startPlot, 2)
  local foodCount = 0
  for _, candidate in ipairs(candidates) do
    if FOOD_RESOURCES[candidate.plot:GetResourceType(-1)] then foodCount = foodCount + 1 end
  end
  for _, candidate in ipairs(candidates) do
    if foodCount >= 2 then break end
    local plot = candidate.plot
    if plot:GetResourceType(-1) == -1 then
      local resourceID = preferredFoodResource(plot)
      if resourceID and plot:CanHaveResource(resourceID, true) then
        plot:SetResourceType(resourceID, 1)
        foodCount = foodCount + 1
      end
    end
  end
  -- The terrain-based choices above are valid Civ V combinations. This final
  -- fallback makes the food guarantee robust if normal placement restrictions
  -- reject every remaining empty plot because of nearby resources.
  for _, candidate in ipairs(candidates) do
    if foodCount >= 2 then break end
    local plot = candidate.plot
    if plot:GetResourceType(-1) == -1 then
      local resourceID = preferredFoodResource(plot)
      if resourceID then
        plot:SetResourceType(resourceID, 1)
        foodCount = foodCount + 1
      end
    end
  end
  return foodCount
end


local function placeRegionalResource(startPlot, resourceType, amount, maximumDistance)
  local resourceID = GameInfoTypes[resourceType]
  if not resourceID then return false end
  for _, candidate in ipairs(nearbyPlots(startPlot, maximumDistance)) do
    local plot = candidate.plot
    if plot:GetResourceType(-1) == -1 and plot:CanHaveResource(resourceID, true) then
      plot:SetResourceType(resourceID, amount)
      return true
    end
  end
  return false
end


local function placeRegionalResourceWithFallbacks(startPlot, preferredType, amount, maximumDistance, fallbacks, excludedType)
  if preferredType ~= excludedType and placeRegionalResource(startPlot, preferredType, amount, maximumDistance) then
    return preferredType
  end
  for _, resourceType in ipairs(fallbacks) do
    if resourceType ~= preferredType and resourceType ~= excludedType and placeRegionalResource(startPlot, resourceType, amount, maximumDistance) then
      return resourceType
    end
  end
  return nil
end


local function placeMediterraneanSeafood()
  local fish = GameInfoTypes.RESOURCE_FISH
  local placed = 0
  for _, position in ipairs(MEDITERRANEAN_SEAFOOD) do
    local plot = Map.GetPlot(position[1], position[2])
    if plot and plot:GetResourceType(-1) == -1 and plot:CanHaveResource(fish, true) then
      plot:SetResourceType(fish, 1)
      placed = placed + 1
    end
  end
  print("Historical Europe TSL: placed " .. placed .. " additional Mediterranean seafood resources")
end


local function placeTSLResources()
  for playerID = 0, GameDefines.MAX_MAJOR_CIVS - 1 do
    local player = Players[playerID]
    if player and player:IsEverAlive() then
      local startPlot = player:GetStartingPlot()
      local civilization = GameInfo.Civilizations[player:GetCivilizationType()]
      if startPlot then
        local foodCount = guaranteeStartingFood(startPlot)
        local package = civilization and TSL_RESOURCE_PACKAGES[civilization.Type]
        if package then
          local firstLuxury = placeRegionalResourceWithFallbacks(startPlot, package.primaryLuxury, 1, 4, {
            "RESOURCE_WINE", "RESOURCE_SALT", "RESOURCE_INCENSE", "RESOURCE_FUR",
            "RESOURCE_SILVER", "RESOURCE_GOLD", "RESOURCE_MARBLE"
          }, nil)
          placeRegionalResourceWithFallbacks(startPlot, package.secondaryLuxury, 1, 5, {
            "RESOURCE_WINE", "RESOURCE_SALT", "RESOURCE_INCENSE", "RESOURCE_FUR",
            "RESOURCE_SILVER", "RESOURCE_GOLD", "RESOURCE_MARBLE"
          }, firstLuxury)
          placeRegionalResourceWithFallbacks(startPlot, package.strategic, 2, 4, {
            "RESOURCE_HORSE", "RESOURCE_IRON", "RESOURCE_COAL"
          }, nil)
        end
        print("Historical Europe TSL: guaranteed " .. foodCount .. " food resources for " .. (civilization and civilization.Type or playerID))
      end
    end
  end
end


local function farEnoughFromStarts(x, y, occupied, minimumDistance)
  for _, position in ipairs(occupied) do
    if Map.PlotDistance(x, y, position[1], position[2]) < minimumDistance then return false end
  end
  return true
end


local function chooseMinorPlot(start, occupied)
  local bestPlot, bestDistance = nil, 999
  for radius = 0, 8 do
    for y = math.max(0, start[2] - radius), math.min(HEIGHT - 1, start[2] + radius) do
      for x = math.max(0, start[1] - radius), math.min(WIDTH - 1, start[1] + radius) do
        local distance = Map.PlotDistance(start[1], start[2], x, y)
        if distance <= radius and distance < bestDistance then
          local plot = Map.GetPlot(x, y)
          if plot and not plot:IsWater() and not plot:IsMountain() and farEnoughFromStarts(x, y, occupied, 4) then
            bestPlot, bestDistance = plot, distance
          end
        end
      end
    end
    if bestPlot then return bestPlot end
  end
  return nil
end


local function assignMinorTSL(occupied)
  for playerID = GameDefines.MAX_MAJOR_CIVS, GameDefines.MAX_CIV_PLAYERS - 1 do
    local player = Players[playerID]
    if player and player:IsEverAlive() and player:IsMinorCiv() then
      local minor = GameInfo.MinorCivilizations[player:GetMinorCivType()]
      local start = minor and MINOR_TSL[minor.Type]
      if start then
        local plot = chooseMinorPlot(start, occupied)
        if plot then
          player:SetStartingPlot(plot)
          occupied[#occupied + 1] = {plot:GetX(), plot:GetY()}
        end
      end
    end
  end
end

function StartPlotSystem()
  local database = AssignStartingPlots.Create()
  database:GenerateRegions()
  database:ChooseLocations()
  database:BalanceAndAssign()
  database:PlaceNaturalWonders()
  database:PlaceResourcesAndCityStates()
  placeMediterraneanSeafood()
  local occupied = assignTSL()
  placeTSLResources()
  assignMinorTSL(occupied)
end
